begin;
select plan(16);
insert into auth.users(id,created_at) values('88888888-8888-8888-8888-888888888888',now()-interval '31 days');
select lives_ok($$select public.pdf_begin('11111111-8888-8888-8888-888888888881','88888888-8888-8888-8888-888888888888',repeat('a',64))$$,'first generation reserves');
select is((select cycle from public.pdf_requests limit 1),1::bigint,'cycle anchored to signup');
select throws_ok($$select public.pdf_begin('11111111-8888-8888-8888-888888888881','88888888-8888-8888-8888-888888888888',repeat('b',64))$$,'P0001','PDF request mismatch','same request cannot generate altered content');
select lives_ok($$select public.pdf_finish(id,owner_id,lease,false) from public.pdf_requests$$,'failed render released');
select lives_ok($$select public.pdf_begin('11111111-8888-8888-8888-888888888881','88888888-8888-8888-8888-888888888888',repeat('a',64))$$,'retry after failure');
select public.pdf_finish(id,owner_id,lease,true) from public.pdf_requests;
select ok((select already_complete from public.pdf_begin('11111111-8888-8888-8888-888888888881','88888888-8888-8888-8888-888888888888',repeat('a',64))),'completed retry does not debit again');
select public.pdf_begin('11111111-8888-8888-8888-888888888882','88888888-8888-8888-8888-888888888888',repeat('a',64));
select public.pdf_begin('11111111-8888-8888-8888-888888888883','88888888-8888-8888-8888-888888888888',repeat('a',64));
select throws_ok($$select public.pdf_begin('11111111-8888-8888-8888-888888888884','88888888-8888-8888-8888-888888888888',repeat('a',64))$$,'P0001','Free PDF allowance reached','reservations prevent concurrent fourth free PDF');
update public.pdf_requests set lease_until=now()-interval '1 second' where state='reserved';
select lives_ok($$select public.pdf_begin('11111111-8888-8888-8888-888888888884','88888888-8888-8888-8888-888888888888',repeat('a',64))$$,'abandoned reservation releases capacity');
select throws_ok($$select public.pdf_finish(id,owner_id,lease,true) from public.pdf_requests where id='11111111-8888-8888-8888-888888888882'$$,'P0001','PDF lease expired','late worker cannot finalize expired reservation');
set local role authenticated;
select throws_ok($$select public.pdf_begin('11111111-8888-8888-8888-888888888885','88888888-8888-8888-8888-888888888888',repeat('a',64))$$,'42501','permission denied for function pdf_begin','browser cannot forge reservations');
reset role;
select is((select remaining from public.pdf_status('88888888-8888-8888-8888-888888888888')),1,'status counts completed and active leases, excludes expired leases');
select is((select resets_at from public.pdf_status('88888888-8888-8888-8888-888888888888')),now()+interval '29 days','status reset uses signup boundary');
insert into public.billing_entitlements(owner_id,paid_through) values('88888888-8888-8888-8888-888888888888',now()+interval '1 day');
select ok((select is_pro from public.pdf_status('88888888-8888-8888-8888-888888888888')),'status confirms active Pro');
select public.pdf_begin('11111111-8888-8888-8888-888888888885','88888888-8888-8888-8888-888888888888',repeat('a',64));
select ok((select not counts_free from public.pdf_requests where id='11111111-8888-8888-8888-888888888885'),'Pro generation does not debit free allowance');
update public.billing_entitlements set paid_through=now() where owner_id='88888888-8888-8888-8888-888888888888';
select ok((select not is_pro from public.pdf_status('88888888-8888-8888-8888-888888888888')),'exact expiry is no longer Pro');
set local role authenticated;
select throws_ok($$select public.pdf_status('88888888-8888-8888-8888-888888888888')$$,'42501','permission denied for function pdf_status','browser cannot query another owner allowance');
reset role;
select * from finish();
rollback;
